async function perform(ops,forExport=false,signal=replayAbort?.signal){
  engine.clear();let done=0;replayLivingOperations=[];livingRenderer.invalidate();wakeLiving();
  const units=op=>op.strokes?op.strokes.reduce((n,o)=>n+units(o),0):(op.points?.length||1)+(op.settle?.ticks||0);
  const total=ops.reduce((n,o)=>n+units(o),0),speed=+$('replaySpeed').value;
  for(const op of ops){
    if(stop)break;
    showPlaying(op);
    if(op.kind==='living-fill'&&op.tool==='livingbrush'){
      const started=performance.now();
      for(let i=0;i<op.points.length;i++){
        if(stop)throw Error('Replay stopped.');
        const target=(op.points[i].t-op.points[0].t)/speed;
        await previewDelay(Math.max(0,target-(performance.now()-started)),signal);
        replayLivingOperations=[...replayLivingOperations.filter(item=>item.id!==op.id),i===op.points.length-1?op:{...op,progress:i+1}];
        wakeLiving();done++;
      }
      await previewDelay(90,signal);
      continue;
    }
    await engine.apply(op,async(i,_length,event)=>{
      if(stop)throw Error('Replay stopped.');done++;$('exportProgress').value=done/Math.max(total,1);
      if(event?.kind==='wet')await previewDelay(event.duration/speed,signal);
      else if(i%2===0){const points=op.points,dt=points&&i?points[i].t-points[Math.max(0,i-2)].t:20;await previewDelay(clamp(dt/speed,5,45),signal);}
    });
    replayLivingOperations=[...replayLivingOperations,op];wakeLiving();
    if(!op.points&&!op.strokes){done++;await previewDelay(forExport?120:90,signal);}
  }
}

