const capturedKeys=new Set();
document.addEventListener('keydown',guarded(async e=>{
  const nativeSpace=(e.code==='Space'||e.key===' ')&&e.target.matches?.('input[type=checkbox],input[type=radio],input[type=color],input[type=file],summary');
  const action=nativeSpace?null:shortcutAction(e,{editable:editableTarget(e.target),dialog:!!document.querySelector('dialog[open]')});
  if(action==='escape'){
    if(selectionDrag){e.preventDefault();e.stopImmediatePropagation();cancelSelection();return;}
    if(previewing||exporting){e.preventDefault();e.stopImmediatePropagation();stopPreview();if(exporting)await window.desktop.cancelExport();return;}
    if(document.querySelector('dialog[open]')||editableTarget(e.target))return;
    if(!drawing){e.preventDefault();selection=null;selectionMaskPreview=null;videoSelectSample=null;clearTimeout(videoSelectTimer);$('selectionPanel').hidden=true;drawSelection();}return;
  }
  if(action){
    e.preventDefault();e.stopImmediatePropagation();capturedKeys.add(e.code||e.key);
    if(e.repeat&&!['smaller','larger'].includes(action))return;
    if(['undo','redo','save','export','open'].includes(action)&&previewing){stopPreview();await previewDone;}
    if(action==='replay'){if(!busy&&!drawing&&!selectionDrag)await replay();return;}
    if(action==='fit'){if(!drawing&&!selectionDrag){fitMode=true;fit();}return;}
    if(busy||drawing||selectionDrag)return;
    if(action==='smaller'||action==='larger'){state.size=clamp(state.size+(action==='larger'?8:-8),2,512);syncControls();return;}
    $({undo:'undo',redo:'redo',save:'save',export:'export',open:'open'}[action])?.click();return;
  }
  if(editableTarget(e.target)||document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.isComposing)return;
  if(selection&&e.key.startsWith('Arrow')&&!busy&&!drawing){e.preventDefault();const n=e.shiftKey?10:1,dx=e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0,dy=e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0;if(selection.objectId&&transformPlacedView({...selection,x:selection.x+dx,y:selection.y+dy}))return;const op={kind:'selection',rect:structuredClone(selection),action:'move',dx,dy,seed:seed()};engine.selection(op);selection.x+=dx;selection.y+=dy;if(selection.path)selection.path=selection.path.map(p=>({...p,x:p.x+dx,y:p.y+dy}));commit(op);drawSelection();}
}),true);
// Space's native button activation happens on keyup; consume the paired event too.
